<?php
 namespace Pterodactyl\Console\Commands\Dezerx; use Illuminate\Console\Command; use Pterodactyl\Models\Dezerx\StaffRequest; use Pterodactyl\Services\Dezerx\Staff\Staff; use Pterodactyl\Services\Dezerx\Staff\StaffNotify; use Pterodactyl\Services\Dezerx\Staff\StaffRequests; use Throwable; class RunStaffSweep extends Command { protected $signature = 'dezerx:staff-sweep'; protected $description = 'End support staff sessions that are out of time and clear away requests nobody took.'; public function handle(StaffRequests $requests): int { if (!Staff::enabled()) { return 0; } $this->expireSessions($requests); $this->expireWaiting($requests); $this->warnExpiring(); return 0; } private function expireSessions(StaffRequests $requests): void { $due = StaffRequest::query() ->where('status', StaffRequest::ACTIVE) ->whereNotNull('expires_at') ->where('expires_at', '<=', now()) ->get(); foreach ($due as $request) { try { $requests->expire($request); } catch (Throwable $exception) { $this->error('Could not end session ' . $request->uuid . ': ' . $exception->getMessage()); } } } private function expireWaiting(StaffRequests $requests): void { $ttl = Staff::number('queue_ttl_minutes'); if ($ttl <= 0) { return; } $stale = StaffRequest::query() ->whereIn('status', [StaffRequest::PENDING, StaffRequest::CLAIMED]) ->where('created_at', '<=', now()->subMinutes($ttl)) ->get(); foreach ($stale as $request) { try { $requests->expire($request); } catch (Throwable $exception) { $this->error('Could not clear request ' . $request->uuid . ': ' . $exception->getMessage()); } } } private function warnExpiring(): void { $window = Staff::number('reminder_minutes'); if ($window <= 0) { return; } $soon = StaffRequest::query() ->where('status', StaffRequest::ACTIVE) ->whereNull('reminded_at') ->whereNotNull('expires_at') ->where('expires_at', '>', now()) ->where('expires_at', '<=', now()->addMinutes($window)) ->get(); foreach ($soon as $request) { try { $request->forceFill(['reminded_at' => now()])->saveOrFail(); StaffNotify::expiring($request, max(1, (int) $request->minutesLeft())); } catch (Throwable $exception) { $this->error('Could not warn about session ' . $request->uuid . ': ' . $exception->getMessage()); } } } } 